<?php
/** Independent source-vs-daily-publication totals; no private record output. */
use Drupal\lit_contribution\Service\{AggregateBuilder,SubmissionDates};
$source=\Drupal::service('lit_contribution.source')->listSubmissions();$rows=\Drupal::service('lit_contribution.reviews')->rows();$dto=\Drupal::service('lit_contribution.publication')->publicData()['survey'];$today=new DateTimeImmutable('now',new DateTimeZone('America/New_York'));
$cases=[['name'=>'all-en','languages'=>['en'],'from'=>'','through'=>''],['name'=>'all-union','languages'=>['en','es'],'from'=>'','through'=>''],['name'=>'last30','languages'=>['en','es'],'from'=>$today->modify('-29 days')->format('Y-m-d'),'through'=>$today->format('Y-m-d')],['name'=>'last90','languages'=>['en','es'],'from'=>$today->modify('-89 days')->format('Y-m-d'),'through'=>$today->format('Y-m-d')],['name'=>'year','languages'=>['en','es'],'from'=>$today->format('Y').'-01-01','through'=>$today->format('Y-m-d')],['name'=>'spring-dst','languages'=>['en','es'],'from'=>'2026-03-08','through'=>'2026-03-08'],['name'=>'fall-dst','languages'=>['en','es'],'from'=>'2026-11-01','through'=>'2026-11-01']];
foreach($cases as &$case){$expected=0;$county=[];$town=[];
 foreach($rows as $r){$s=$source[$r['survey_id'].'/'.$r['response_id']]??NULL;if(in_array(TRUE,AggregateBuilder::exclusions($s,$r),TRUE))continue;$d=(new DateTimeImmutable($s['submitted_at']))->setTimezone(new DateTimeZone('America/New_York'))->format('Y-m-d');if(($case['from'] && $d<$case['from']) || ($case['through'] && $d>$case['through']))continue;$positive=array_keys(array_filter($s['answers']['languages'],fn($p)=>$p['uses_language']==='yes'));if(!array_intersect($positive,$case['languages']))continue;$expected++;$c=$s['answers']['county_geoid'];$m=$s['answers']['municipality']??'_unspecified';$county[$c]=($county[$c]??0)+1;$town[$c][$m]=($town[$c][$m]??0)+1;}
 $actual=0;foreach($dto['days'] as $d)if(SubmissionDates::includes($d['day'],$case['from'],$case['through']))foreach($d['combinations'] as $g)if(array_intersect($g['languages'],$case['languages']))$actual+=$g['count'];if($actual!==$expected)throw new RuntimeException('Daily source mismatch '.$case['name']);$case+=['total'=>$expected,'counties'=>$county,'towns'=>$town];
}unset($case);file_put_contents(dirname(DRUPAL_ROOT).'/private/union-qa/questionnaire-date-expected.json',json_encode($cases,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));echo json_encode(array_map(fn($c)=>array_intersect_key($c,array_flip(['name','from','through','total'])),$cases),JSON_PRETTY_PRINT).PHP_EOL;
